code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = y+dy, x+dx
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        q.append(p)
            top, left = min(y for y,x in cells), min(x for y,x in cells)
            bottom, right = max(y for y,x in cells), max(x for y,x in cells)
            hh, ww = bottom-top+1, right-left+1
            rel = {(y-top, x-left) for y,x in cells}
            ring = hh >= 3 and ww >= 3 and rel == ({(y,x) for y in range(hh) for x in range(ww) if y in (0,hh-1) or x in (0,ww-1)})
            objects.append({'cells': cells, 'rel': rel, 'color': color, 'x': left, 'y': top, 'hh': hh, 'ww': ww, 'ring': ring})
    placed = []
    out = [[0]*w for _ in range(h)]
    for is_ring, seq, ys in ((True, sorted([o for o in objects if o['ring']], key=lambda o:(o['y'],o['x'])), range(h)),
                             (False, sorted([o for o in objects if not o['ring']], key=lambda o:(-o['y'],-o['x'])), range(h-1,-1,-1))):
        occupied = set()
        for o in placed:
            occupied |= o['abs']
        for o in seq:
            feasible = [y for y in ys if 0 <= y <= h-o['hh'] and not any((y+dy,o['x']+dx) in occupied for dy,dx in o['rel'])]
            if not feasible:
                # no valid packing under this direction; retain original location
                y = o['y']
            else:
                y = feasible[0]
            abs_cells = {(y+dy,o['x']+dx) for dy,dx in o['rel']}
            placed.append({'abs':abs_cells,'color':o['color']})
            for yy,xx in abs_cells:
                out[yy][xx]=o['color']
            occupied |= abs_cells
    return out
'''
